define(["core/ajax","core/templates","core/notification"],function(Ajax,Templates,Notification){const init=function(bookflowId){const form=document.querySelector("[data-region='bookflow-search']");if(!form){return}form.addEventListener("submit",function(event){event.preventDefault();const query=form.querySelector("input").value.trim();if(query.length<2){return}Ajax.call([{methodname:"mod_bookflow_search_contents",args:{bookflowid:bookflowId,query:query}}])[0].then(function(results){return Templates.renderForPromise("mod_bookflow/search_results",{results:results})}).then(function(result){Templates.replaceNodeContents(form.querySelector("[data-region='search-results']"),result.html,result.js);return true}).catch(Notification.exception)})};return{init:init}});